import fitz, json, numpy as np
d=fitz.open('eprint/exclusion.pdf')
p=d[0]
dd=p.get_drawings()[18]
def tolog(x,y):
    return (-9+(x-107.4677)/39.4478, -9+(228.9915-y)/24.1128)
poly=[]
for it in dd['items']:
    if it[0]=='l':
        seg=[(it[1].x,it[1].y),(it[2].x,it[2].y)]
    elif it[0]=='c':
        p0,p1,p2,p3=[(q.x,q.y) for q in it[1:5]]
        seg=[]
        for t in np.linspace(0,1,12):
            mt=1-t
            x=mt**3*p0[0]+3*mt**2*t*p1[0]+3*mt*t**2*p2[0]+t**3*p3[0]
            y=mt**3*p0[1]+3*mt**2*t*p1[1]+3*mt*t**2*p2[1]+t**3*p3[1]
            seg.append((x,y))
    else: continue
    if poly and abs(seg[0][0]-poly[-1][0])<1e-6 and abs(seg[0][1]-poly[-1][1])<1e-6:
        poly+=seg[1:]
    else: poly+=seg
logs=[tolog(x,y) for x,y in poly]
for i,(lx,ly) in enumerate(logs):
    if abs(ly)<0.01 and abs(lx+8.992)<0.01: start=i; break
curve=[c for c in logs[start:] if not (c[1]>-0.01 and c[0]>-8.9)]
print('full curve pts:',len(curve),'min ly:',min(c[1] for c in curve),'at lx=', min(curve,key=lambda c:c[1])[0])
sel=[curve[0]]
for c in curve[1:]:
    thr = 0.02 if c[1]<-7.0 else 0.15
    if abs(c[0]-sel[-1][0])>thr or abs(c[1]-sel[-1][1])>thr:
        sel.append(c)
if sel[-1]!=curve[-1]: sel.append(curve[-1])
pts=[[float(10**lx),float(10**ly)] for lx,ly in sel]
assert all(pts[i][0]<pts[i+1][0] for i in range(len(pts)-1)), "not monotone"
print(len(pts))
for m,c in pts: print("%.4e %.4e"%(m,c))
json.dump(pts,open('curve_pts.json','w'))
